    path: "Dockerfile",
    name: "Dockerfile",
    language: "dockerfile",
    category: "deploy",
    description: "Hugging Face Spaces compatible Docker image.",
    content: "# Hugging Face Spaces Compatible Dockerfile for EcommerceAICardBot\nFROM python:3.11-slim\n\n# Set environment variables\nENV PYTHONDONTWRITEBYTECODE=1 \\\n    PYTHONUNBUFFERED=1 \\\n    PORT=7860 \\\n    HOME=/home/user \\\n    PATH=/home/user/.local/bin:$PATH\n\nWORKDIR /app\n\n# Install system dependencies\nRUN apt-get update && apt-get install -y --no-install-recommends \\\n    build-essential \\\n    libpq-dev \\\n    curl \\\n    && rm -rf /var/lib/apt/lists/*\n\n# Create Hugging Face user (UID 1000)\nRUN useradd -m -u 1000 user && \\\n    mkdir -p /app && \\\n    chown -R user:user /app\n\n# Install python dependencies as user\nCOPY --chown=user:user requirements.txt .\nUSER user\nRUN pip install --no-cache-dir --upgrade pip && \\\n    pip install --no-cache-dir --user -r requirements.txt\n\n# Copy application files\nCOPY --chown=user:user . .\n\n# Hugging Face Spaces requires port 7860\nEXPOSE 7860\n\n# Run app.py which serves port 7860 healthcheck and runs the Telegram bot concurrently\nCMD [\"python\", \"app.py\"]\n",
