    content: "services:\n  bot:\n    build: .\n    container_name: ecommerce_ai_card_bot\n    restart: unless-stopped\n    env_file:\n      - .env\n    environment:\n      - DATABASE_URL=postgresql+asyncpg://postgres:postgres@db:5432/ecommerce_bot\n    depends_on:\n      db:\n        condition: service_healthy\n\n  db:\n    image: postgres:16-alpine\n    container_name: ecommerce_bot_db\n    restart: unless-stopped\n    environment:\n      POSTGRES_USER: postgres\n      POSTGRES_PASSWORD: postgres\n      POSTGRES_DB: ecommerce_bot\n    volumes:\n      - postgres_data:/var/lib/postgresql/data\n    ports:\n      - \"127.0.0.1:5432:5432\"  # reachable only from this machine, not from the internet\n    healthcheck:\n      test: [\"CMD-SHELL\", \"pg_isready -U postgres -d ecommerce_bot\"]\n      interval: 5s\n      timeout: 5s\n      retries: 5\n\nvolumes:\n  postgres_data:\n",
